def apply_notifications_tables(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        for model_name in ["Template", "Preference", "Delivery", "PushSubscription"]:
            schema_editor.create_model(apps.get_model("notifications", model_name))

def reverse_notifications_tables(apps, schema_editor):
    if schema_editor.connection.vendor != "postgresql":
        for model_name in ["PushSubscription", "Delivery", "Preference", "Template"]:
            schema_editor.delete_model(apps.get_model("notifications", model_name))

